```js
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Listening on port ${PORT}`));
```

If you already have an app, you only need the `app.get('/health', ...)` handler. Register it before any auth middleware so health checks don't require credentials.
